/* ── Tokens ── GENERATED from src/tokens.ts. Do not edit by hand. */
:root {
  --bg: #FAF8F2;                        /* paper */
  --text: #1A1A1A;                      /* ink */
  --text-secondary: #6B6B6B;            /* gray */
  --accent: #1A1A1A;                   /* the "accent" is ink; monochrome */
  --divider: rgba(0,0,0,0.08);
  --divider-subtle: rgba(0,0,0,0.06);
  --table-alt: rgba(0,0,0,0.02);
  --grid-line: rgba(0,0,0,0.04);
  --control-border: rgba(0,0,0,0.42);
  color-scheme: light;
  --radius-sm: 4px;           /* slight Raster radius; standalone buttons */
  --radius: var(--radius-sm);              /* alias — buttons, boxes, dialogs share it; cards stay 0 */
  --radius-chrome: 0px;
  --gutter: 20px;
  --pad: 20px;
  /* Concentric: Steve Ruiz innerRadius result. Closed form of the circular-corner fit. Default radius vs --pad is 0. */
  --radius-in: max(0px, calc(var(--radius) - var(--pad)));
  --ease: cubic-bezier(0.2, 0, 0, 1);
  --duration-snap: 0.12s;
  --duration: 0.18s;
  --duration-confirm: 0.16s;
  --transition: background-color var(--duration) var(--ease), color var(--duration) var(--ease);
  /* Background column grid: 204px modules (184 column + 20 gutter). */
  --grid-image: linear-gradient(to right,var(--grid-line) 0,var(--grid-line) 1px,transparent 1px,transparent 184px,var(--grid-line) 184px,var(--grid-line) 185px,transparent 185px,transparent 204px);
  --grid-size: 204px;
  --grid-pos: 20px 0;
  --text-scale: 1;
  /* Stacking scale. Native dialog and popover use the top layer instead. */
  --z-raised: 10;
  --z-sticky: 100;
  --z-float: 200;
  --z-overlay: 300;
  --z-toast: 400;
  /* Contract variables a component may set inline: concentric radius and the chart spot color. */
  --rs-out: var(--radius);
  --rs-gap: var(--pad);
  --rs-in: var(--radius-in);
  --rs-chart-spot: var(--text);
  /* Control scale. Desktop is the poster; ≤640 recuts every control to 44pt. */
  --hit: 40px;
  --control-h: 40px;
  --control-fs: 14px;
  --control-label: 12px;
}
[data-theme="dark"] {
  --bg: #0E0C0A;
  --text: #E8E8E8;
  --text-secondary: #949494;
  --accent: #E8E8E8;
  --divider: rgba(255,255,255,0.10);
  --divider-subtle: rgba(255,255,255,0.07);
  --table-alt: rgba(255,255,255,0.03);
  --grid-line: rgba(255,255,255,0.05);
  --control-border: rgba(255,255,255,0.38);
  color-scheme: dark;
}
/* System dark scheme applies until the page decides with data-theme. */
@media (prefers-color-scheme: dark) {
:root:not([data-theme="light"]) {
  --bg: #0E0C0A;
  --text: #E8E8E8;
  --text-secondary: #949494;
  --accent: #E8E8E8;
  --divider: rgba(255,255,255,0.10);
  --divider-subtle: rgba(255,255,255,0.07);
  --table-alt: rgba(255,255,255,0.03);
  --grid-line: rgba(255,255,255,0.05);
  --control-border: rgba(255,255,255,0.38);
  color-scheme: dark;
}
}
/* Mobile grid (≤480): two fluid columns, three 25px gutters
   (edge · middle · edge). Column width = 50vw − 37.5px; the background
   draws all four column-edge lines and content lives between the outer pair. */
@media(max-width:480px){
  :root{
    --pad:25px;
    --grid-image:linear-gradient(to right,transparent 0,transparent 25px,var(--grid-line) 25px,var(--grid-line) 26px,transparent 26px,transparent calc(50vw - 12.5px),var(--grid-line) calc(50vw - 12.5px),var(--grid-line) calc(50vw - 11.5px),transparent calc(50vw - 11.5px),transparent calc(50vw + 12.5px),var(--grid-line) calc(50vw + 12.5px),var(--grid-line) calc(50vw + 13.5px),transparent calc(50vw + 13.5px),transparent calc(100vw - 26px),var(--grid-line) calc(100vw - 26px),var(--grid-line) calc(100vw - 25px),transparent calc(100vw - 25px));
    --grid-size:100vw;
    --grid-pos:0 0;
  }
}
/* Phone control scale (≤640): 44pt hits, 16px type on fields. */
@media(max-width:640px){
  :root{
    --hit:44px;
    --control-h:44px;
    --control-fs:16px;
    --control-label:15px;
  }
}

/* ── Base ──
   Raster owns the page: paper on html, ink on body, and quiet
   gutter verticals on html::before so overflow-x:clip cannot drop
   them. --grid-pos: 20px 0 puts the first tile line on the left
   20px gutter; that utmost left gutter must paint. Do not clip
   it. No 204 horizontals — those cage the type. Homepage and
   About kill this overlay and keep boxed cells only. */
html{scroll-behavior:smooth;overflow-x:clip;background-color:var(--bg)}
html::before{
  content:"";
  position:fixed;
  inset:0;
  z-index:0;
  pointer-events:none;
  background-image:var(--grid-image);
  background-size:var(--grid-size) 100%;
  background-repeat:repeat-x;
  background-position:var(--grid-pos)
}
body{
  position:relative;
  z-index:1;
  overflow-x:clip;
  background-color:transparent;
  color:var(--text);
  font-family:Inter,-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;
  font-weight:500;
  line-height:1.6;
  transition:var(--transition);
  -webkit-font-smoothing:antialiased;
}

/* ── Utilities ── */
.rs-sr{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.rs-sr:focus-visible+.rs-check,.rs-sr:focus-visible+.rs-radio-dot,.rs-sr:focus-visible+.rs-switch{outline:1.5px solid var(--text);outline-offset:2px}

/* ── Type scale ──
   Hierarchy from weight, color, and position; never all caps.
   --text-scale (Appearance → Text size) multiplies reading type only. */
.rs-t-xl{font-size:calc(clamp(34px,5vw,52px) * var(--text-scale, 1));font-weight:600;letter-spacing:-.035em;line-height:1.05;color:var(--text);margin:0;text-wrap:balance}
.rs-t-display{font-size:calc(2.375rem * var(--text-scale, 1));font-weight:600;letter-spacing:-.03em;line-height:1.15;color:var(--text);margin:0;text-wrap:balance}
.rs-t-title{font-size:calc(1.375rem * var(--text-scale, 1));font-weight:600;letter-spacing:-.02em;line-height:1.3;color:var(--text);margin:0;text-wrap:balance}
.rs-t-sub{font-size:calc(1.0625rem * var(--text-scale, 1));font-weight:500;letter-spacing:-.01em;line-height:1.5;color:var(--text-secondary);margin:0;text-wrap:pretty}
.rs-t-body{font-size:calc(0.9375rem * var(--text-scale, 1));font-weight:500;letter-spacing:-.01em;line-height:1.6;color:var(--text);margin:0;text-wrap:pretty}
.rs-t-label{font-size:calc(0.8125rem * var(--text-scale, 1));font-weight:600;letter-spacing:-.01em;line-height:1.3;color:var(--text);margin:0}

/* ── Inline code ── */
.rs-code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.88em;color:var(--text);background:var(--table-alt);padding:1px 5px;border-radius:var(--radius-sm);letter-spacing:0}

/* ── Touch: no hover-only reveal. Focus or press shows the overlay. ── */
@media(hover:none){
  .rs-btn-primary:hover{opacity:1}
  .rs-btn-primary:active{opacity:.85}
  .rs-btn-ghost:hover{background:transparent;border-color:var(--divider)}
  .rs-btn-ghost:active{background:var(--divider);border-color:transparent}
  .rs-cal-day:hover{background:none}
  .rs-cal-day:active{background:var(--divider-subtle)}
  .rs-hover-card:hover .rs-hover-card-panel{opacity:0;visibility:hidden}
  .rs-hover-card:focus-within .rs-hover-card-panel,
  .rs-hover-card:active .rs-hover-card-panel{opacity:1;visibility:visible}
  .rs-tip:hover::after{opacity:0}
  .rs-tip:focus-within::after,
  .rs-tip:active::after{opacity:1}
  .rs-link:hover{border-color:var(--divider)}
  .rs-link:active{border-color:var(--accent)}
  .rs-link-underline:hover{background-image:linear-gradient(var(--divider),var(--divider))}
  .rs-link-underline:active{background-image:linear-gradient(var(--accent),var(--accent))}
}

/* ── Reduced motion: nothing loops, nothing slides, nothing enters ── */
@media(prefers-reduced-motion:reduce){
  .rs-reveal,.rs-crumb-bar .rs-crumbs,.rs-tip::after,.rs-hover-card-panel{transition:none}
  .rs-subscribed,.rs-toast{animation:none}
  .rs-theme-sun,.rs-theme-moon{transition:none}
  .rs-spinner svg{animation:none}
}
